  {
    "id": "prisma-schema-and-generation",
    "title": "Define Kudo model in Prisma schema and generate client",
    "goal": "The Kudo model is appended below the MODEL SLOT marker in prisma/schema.prisma with id, sender, receiver, message, and createdAt. Running prisma generate succeeds with the client updating to support the Kudo model schema.",
    "files_hint": [
      "prisma/schema.prisma"
    ]
  },
  {
    "id": "kudos-prisma-and-kudos-services",
    "title": "Implement PrismaService and KudosService",
    "goal": "Create PrismaService (wrapper extending PrismaClient implementing OnModuleInit) and KudosService (injecting PrismaService, supporting create(data) and findAll() sorted descending by createdAt and id) inside src/modules/kudos/.",
    "files_hint": [
      "src/modules/kudos/prisma.service.ts",
      "src/modules/kudos/kudos.service.ts"
    ]
  },
  {
    "id": "kudos-controller-and-registration",
    "title": "Implement KudosController, KudosModule and register in application",
    "goal": "Create KudosController under @Controller('kudos') supporting POST (with manual validation failing empty, non-string, over-length or missing inputs, and trimming sender, receiver, message before saving) and GET endpoints. Create KudosModule, reference controller/services, and register it inside the MODULES array in src/modules/index.ts.",
    "files_hint": [
      "src/modules/kudos/kudos.controller.ts",
      "src/modules/kudos/kudos.module.ts",
      "src/modules/index.ts"
    ]
  },
  {
    "id": "kudos-integration-testing",
    "title": "Implement integration tests with Vitest",
    "goal": "Create test/modules/kudos.spec.ts testing real SQLite DB interactions. Tests must verify: valid user post creation (201 response with trimmed properties), validation failures (400 response with BadRequestException for non-string, empty/whitespace, missing, or excessively long sender/receiver/message), empty GET list (200 with []), and properly sorted GET listings. Ensure health checks also reflect 1 registered module.",
    "files_hint": [
      "test/modules/kudos.spec.ts"
    ]
  }
]
